// Always 401 — clears the browser's Basic Auth cache when the client hits it with dummy credentials.
app.get('/api/logout', (req, res) => {
  res.set('Cache-Control', 'no-store');
  res.set('WWW-Authenticate', 'Basic realm="Elysian Command Center"');
  res.status(401).send('Logged out');
});

if (APP_PASSWORD || USERS.length) {
  app.use((req, res, next) => {
    if (req.path === '/health' || req.path === '/api/fe-info' || req.path === '/api/logout') return next();
    const b64 = (req.headers['authorization'] || '').replace(/^Basic\s+/i, '');
    let u = '', pw = '';
    try { const s = Buffer.from(b64, 'base64').toString(); const i = s.indexOf(':'); u = i < 0 ? '' : s.slice(0, i); pw = i < 0 ? s : s.slice(i + 1); } catch (e) {}
    const acct = USERS.find(x => x.user.toLowerCase() === String(u).toLowerCase() && x.pass === pw);
    if (acct) { req.acctUser = acct.user; req.acctAccess = acct.access; req.acctProfile = acct.profile; req.acctProfiles = acct.profiles; return next(); }
    if (APP_PASSWORD && pw === APP_PASSWORD) { req.acctUser = u || 'admin'; req.acctAccess = 'all'; req.acctProfile = 'management'; req.acctProfiles = ['management']; return next(); }
    res.set('WWW-Authenticate', 'Basic realm="Elysian Command Center"');
    res.status(401).send('Authentication required');
  });
}

// ── Middleware ────────────────────────────────────────────────────────────────
app.use(express.static(__dirname));
app.use(express.json({ limit: '50mb' }));

